import type { ArchiveScope, IsoTimestamp, SoftDeletable } from "@/types/common";
import { toIsoTimestamp } from "@/types/common";

/**
 * Soft-delete conventions.
 *
 * Issues, projects and comments are archived with an `archived_at` timestamp
 * rather than removed on the spot. Repositories must express "live rows only"
 * through these helpers so the predicate stays in one place; a raw
 * `isNull(table.archivedAt)` sprinkled through the data layer is exactly the
 * drift this module prevents. An archived issue stays restorable until the
 * plan's retention window elapses; the sweep then purges it for good.
 */

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** Reasons a restore is refused after the caller has already been authorized. */
export type RestoreRefusalReason =
  | "not_archived"
  | "expired"
  | "project_archived"
  | "quota";

