/** The column patch that restores an archived row. */
export function restorePatch(now: Date = new Date()): {
  archivedAt: null;
  updatedAt: IsoTimestamp;
} {
  return { archivedAt: null, updatedAt: toIsoTimestamp(now) };
}

input.new_string:
/** The column patch that restores an archived row. */
export function restorePatch(now: Date = new Date()): {
  archivedAt: null;
  updatedAt: IsoTimestamp;
} {
  return { archivedAt: null, updatedAt: toIsoTimestamp(now) };
}

/**
 * Instant at which an archive becomes permanent: `retentionDays` × 24h before
 * `now`. A row archived at this instant has expired; anything later has not.
 */
export function retentionCutoff(retentionDays: number, now: Date): IsoTimestamp {
  return toIsoTimestamp(new Date(now.getTime() - retentionDays * MS_PER_DAY));
}

/**
 * True once the plan's retention window has elapsed since `archivedAt`.
 * A live row is never expired. The cut-off instant itself counts as expired,
 * matching the retention sweep.
 */
export function isRetentionExpired(
  row: SoftDeletable,
  retentionDays: number,
  now: Date = new Date(),
): boolean {
  if (!isArchived(row) || row.archivedAt === null) return false;
  return row.archivedAt <= retentionCutoff(retentionDays, now);
}

