/**
 * Next per-project issue number. Archived issues keep their number, and a
 * purged issue's number stays reserved: the max is taken over every remaining
 * row and over the high-water mark recorded when a row is purged.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const db = getDb();
  const row = db
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();

  const watermark = db
    .select({ highestNumber: issueNumberWatermarks.highestNumber })
    .from(issueNumberWatermarks)
    .where(
      and(
        orgPredicate(issueNumberWatermarks.orgId, orgId),
        eq(issueNumberWatermarks.projectId, projectId),
      ),
    )
    .get();

  return Math.max(row?.value ?? 0, watermark?.highestNumber ?? 0) + 1;
}

/**
 * Archived issues whose `archivedAt` is at or before `cutoff` — the retention
 * sweep's work list. Every project of the org is included, with no page cap.
 */
export async function listExpiredIssues(
  orgId: OrgId,
  cutoff: IsoTimestamp,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        isNotNull(issues.archivedAt),
        lte(issues.archivedAt, cutoff),
      ),
    )
    .all();

  return rows.map((row) => toIssue(row));
}

const BYTES_PER_MB = 1024 * 1024;

/**
 * Permanently deletes an archived issue and the rows that belong to it:
 * label links, comments and attachments. The issue's number is recorded
 * first so a later create in the same project cannot reuse it. Returns the
 * comment ids (so their search documents can be dropped) and the megabytes
 * the attachments were counted for — each size rounded up to a whole
 * megabyte. A missing or live issue is left untouched.
 */
export async function purgeIssue(
  orgId: OrgId,
  issueId: IssueId,
): Promise<{ commentIds: readonly string[]; storageMb: number } | null> {
  const db = getDb();
  const issue = db
    .select()
    .from(issues)
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .get();

  if (!issue || issue.archivedAt === null) return null;

  const commentRows = db
    .select({ id: comments.id })
    .from(comments)
    .where(
      and(orgPredicate(comments.orgId, orgId), eq(comments.issueId, issueId)),
    )
    .all();

  const attachmentRows = db
    .select({ sizeBytes: attachments.sizeBytes })
    .from(attachments)
    .where(
      and(
        orgPredicate(attachments.orgId, orgId),
        eq(attachments.issueId, issueId),
      ),
    )
    .all();

  const storageMb = attachmentRows.reduce(
    (sum, row) => sum + Math.ceil(row.sizeBytes / BYTES_PER_MB),
    0,
  );

  db.transaction((tx) => {
    const existing = tx
      .select({ highestNumber: issueNumberWatermarks.highestNumber })
      .from(issueNumberWatermarks)
      .where(
        and(
          orgPredicate(issueNumberWatermarks.orgId, orgId),
          eq(issueNumberWatermarks.projectId, issue.projectId),
        ),
      )
      .get();

    if (!existing) {
      tx.insert(issueNumberWatermarks)
        .values({
          orgId,
          projectId: issue.projectId,
          highestNumber: issue.number,
        })
        .run();
    } else if (issue.number > existing.highestNumber) {
      tx.update(issueNumberWatermarks)
        .set({ highestNumber: issue.number })
        .where(
          and(
            orgPredicate(issueNumberWatermarks.orgId, orgId),
            eq(issueNumberWatermarks.projectId, issue.projectId),
          ),
        )
        .run();
    }

    tx.delete(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.issueId, issueId),
        ),
      )
      .run();
    tx.delete(comments)
      .where(
        and(orgPredicate(comments.orgId, orgId), eq(comments.issueId, issueId)),
      )
      .run();
    tx.delete(attachments)
      .where(
        and(
          orgPredicate(attachments.orgId, orgId),
          eq(attachments.issueId, issueId),
        ),
      )
      .run();
    tx.delete(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .run();
  });

  return {
    commentIds: commentRows.map((row) => row.id),
    storageMb,
  };
}

