/**
 * Temporary verification for restore and purge. Deleted after the run.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
import { and, eq } from "drizzle-orm";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { getPlanLimits } from "@/config/plan-limits";
import { subscribe } from "@/lib/event-bus";
import { toAppError } from "@/lib/errors";
import { PermissionDeniedError } from "@/lib/permissions";
import { RestoreRefusedError, retentionCutoff } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { getDb, issueLabels, issues } from "@/server/db";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as attachmentRepo from "@/server/repositories/attachment-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { registerActivityListeners } from "@/server/services/activity-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { registerSearchListeners, search } from "@/server/services/search-service";
import { registerUsageListeners } from "@/server/services/usage-service";
import { NotFoundError } from "@/server/services/_support";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { IssueId, OrgId } from "@/types/common";

const NOW = new Date("2026-06-15T12:00:00.000Z");

let cleanup: () => void;
let tenant: Tenant;
const offs: Array<() => void> = [];

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  offs.push(registerActivityListeners());
  offs.push(registerSearchListeners());
  offs.push(registerUsageListeners());
  tenant = await createTenant("restore");
  await usageRepo.recomputeUsage(tenant.org.id);
});

afterAll(() => {
  for (const off of offs) off();
  cleanup();
});

async function backdate(orgId: OrgId, issueId: IssueId, when: string): Promise<void> {
  getDb()
    .update(issues)
    .set({ archivedAt: when })
    .where(and(eq(issues.orgId, orgId), eq(issues.id, issueId)))
    .run();
}

describe("restoreIssue", () => {
  it("restores the original number and publishes issue.restored", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Bring me back" }),
    );
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);

    const seen: unknown[] = [];
    const off = subscribe("issue.restored", (payload) => {
      seen.push(payload);
    });

    try {
      const restored = await issueService.restoreIssue(
        tenant.actors.member,
        tenant.org.id,
        issue.id,
      );
      expect(restored.number).toBe(issue.number);
      expect(restored.archivedAt).toBeNull();
      expect(seen).toHaveLength(1);
      expect(seen[0]).toMatchObject({
        issueId: issue.id,
        projectId: issue.projectId,
        actorId: tenant.userIds.member,
      });

      const audit = await activityRepo.listActivity({
        orgId: tenant.org.id,
        action: ["issue.restored"],
        limit: 20,
        cursor: null,
      });
      expect(audit.items.some((row) => row.subjectId === issue.id)).toBe(true);

      const hits = await search(tenant.actors.member, {
        orgId: tenant.org.id,
        q: "Bring me back",
        kinds: ["issue"],
        limit: 10,
        cursor: null,
      });
      expect(hits.items.map((hit) => hit.id)).toContain(issue.id);

      const usage = await usageRepo.getUsage(tenant.org.id);
      const live = await issueRepo.countIssues(tenant.org.id, tenant.project.id);
      expect(usage.issuesUsed).toBeGreaterThanOrEqual(live);
    } finally {
      off();
    }
  });

  it("lets the author restore even as a viewer", async () => {
    const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    const issue = await issueRepo.insertIssue(
      issueInput(tenant.org.id, tenant.project.id, { title: "Viewer authored" }),
      tenant.userIds.viewer,
      number,
    );
    await issueRepo.archiveIssue(tenant.org.id, issue.id);

    const restored = await issueService.restoreIssue(
      tenant.actors.viewer,
      tenant.org.id,
      issue.id,
    );
    expect(restored.archivedAt).toBeNull();
  });

  it("refuses a live issue without writing or publishing", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Still live" }),
    );
    const seen: unknown[] = [];
    const off = subscribe("issue.restored", (payload) => seen.push(payload));
    try {
      await expect(
        issueService.restoreIssue(tenant.actors.member, tenant.org.id, issue.id),
      ).rejects.toMatchObject({ name: "RestoreRefusedError", reason: "not_archived", code: "conflict" });
      expect(seen).toHaveLength(0);
      const still = await issueRepo.findIssueById(tenant.org.id, issue.id);
      expect(still?.archivedAt).toBeNull();
    } finally {
      off();
    }
  });

  it("refuses an expired archive even before the sweep", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Too old" }),
    );
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);
    const days = getPlanLimits(tenant.org.plan).retentionDays;
    await backdate(
      tenant.org.id,
      issue.id,
      new Date(NOW.getTime() - (days + 1) * 24 * 60 * 60 * 1000).toISOString(),
    );

    await expect(
      issueService.restoreIssue(tenant.actors.member, tenant.org.id, issue.id),
    ).rejects.toBeInstanceOf(RestoreRefusedError);

    const still = await issueRepo.findIssueById(tenant.org.id, issue.id);
    expect(still?.archivedAt).not.toBeNull();
  });

  it("refuses when the project is archived", async () => {
    const project = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Shelved",
      slug: "shelved",
      key: "SHV",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, project.id, { title: "In shelved project" }),
    );
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);
    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: project.id,
      archiveIssues: false,
    });

    await expect(
      issueService.restoreIssue(tenant.actors.member, tenant.org.id, issue.id),
    ).rejects.toMatchObject({ reason: "project_archived" });
  });

  it("refuses when the project is at its issue quota", async () => {
    const quotaTenant = await createTenant("restorequota", "free");
    await usageRepo.recomputeUsage(quotaTenant.org.id);
    for (let number = 1; number <= 100; number += 1) {
      await issueRepo.insertIssue(
        issueInput(quotaTenant.org.id, quotaTenant.project.id, {
          title: `Full ${number}`,
        }),
        quotaTenant.userIds.member,
        number,
      );
    }
    const archived = await issueRepo.insertIssue(
      issueInput(quotaTenant.org.id, quotaTenant.project.id, { title: "Parked" }),
      quotaTenant.userIds.member,
      101,
    );
    await issueRepo.archiveIssue(quotaTenant.org.id, archived.id);

    await expect(
      issueService.restoreIssue(
        quotaTenant.actors.member,
        quotaTenant.org.id,
        archived.id,
      ),
    ).rejects.toMatchObject({ reason: "quota" });

    const still = await issueRepo.findIssueById(quotaTenant.org.id, archived.id);
    expect(still?.archivedAt).not.toBeNull();
  });

  it("rejects the wrong org, an unknown id, and a viewer who does not own it", async () => {
    const other = await createTenant("restoreother");
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Guarded" }),
    );
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);

    await expect(
      issueService.restoreIssue(other.actors.owner, tenant.org.id, issue.id),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      issueService.restoreIssue(
        tenant.actors.member,
        tenant.org.id,
        "01HZZZZZZZZZZZZZZZZZZZZZZZ" as IssueId,
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      issueService.restoreIssue(tenant.actors.viewer, tenant.org.id, issue.id),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("maps RestoreRefusedError to conflict", () => {
    const shape = toAppError(new RestoreRefusedError("expired"));
    expect(shape.code).toBe("conflict");
    expect(shape.meta?.reason).toBe("expired");
  });
});

describe("retention sweep purge", () => {
  it("deletes every expired issue and keeps the number, storage, and search honest", async () => {
    const org = await createTenant("purge");
    await usageRepo.getUsage(org.org.id);

    const keep = await issueService.createIssue(
      org.actors.member,
      issueInput(org.org.id, org.project.id, { title: "KeepRecentMarker" }),
    );
    await issueService.archiveIssue(org.actors.member, org.org.id, keep.id);

    const doomed = await issueService.createIssue(
      org.actors.member,
      issueInput(org.org.id, org.project.id, { title: "PurgeMeMarker" }),
    );
    const comment = await commentRepo.insertComment(
      {
        orgId: org.org.id,
        issueId: doomed.id,
        body: "PurgeCommentMarker",
        parentId: null,
        mentionedUserIds: [],
      },
      org.userIds.member,
    );
    const { upsertSearchDocument } = await import("@/server/repositories/search-repository");
    await upsertSearchDocument(org.org.id, "issue", doomed.id, "PurgeMeMarker", doomed.projectId);
    await upsertSearchDocument(org.org.id, "comment", comment.id, "PurgeCommentMarker", null);

    const label = await labelRepo.insertLabel({
      orgId: org.org.id,
      name: "purge-label",
      color: "#112233",
      description: null,
    });
    getDb()
      .insert(issueLabels)
      .values({ orgId: org.org.id, issueId: doomed.id, labelId: label.id })
      .run();

    await attachmentRepo.insertAttachment(
      {
        orgId: org.org.id,
        issueId: doomed.id,
        filename: "a.bin",
        contentType: "application/octet-stream",
        sizeBytes: 1,
      },
      org.userIds.member,
    );
    await attachmentRepo.insertAttachment(
      {
        orgId: org.org.id,
        issueId: doomed.id,
        filename: "b.bin",
        contentType: "application/octet-stream",
        sizeBytes: 1024 * 1024 + 1,
      },
      org.userIds.member,
    );
    await usageRepo.incrementUsage(org.org.id, { storageMbUsed: 1 + 2 });

    const otherProject = await projectService.createProject(org.actors.admin, {
      orgId: org.org.id,
      name: "Other",
      slug: "other",
      key: "OTH",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    const elsewhere = await issueRepo.insertIssue(
      issueInput(org.org.id, otherProject.id, { title: "Other project doomed" }),
      org.userIds.member,
      1,
    );
    await issueRepo.archiveIssue(org.org.id, elsewhere.id);

    const days = getPlanLimits(org.org.plan).retentionDays;
    const old = new Date(NOW.getTime() - (days + 2) * 24 * 60 * 60 * 1000).toISOString();
    await issueService.archiveIssue(org.actors.member, org.org.id, doomed.id);
    await backdate(org.org.id, doomed.id, old);
    await backdate(org.org.id, elsewhere.id, old);

    // More expired issues than the old page size, spread past the first page.
    for (let n = 0; n < 105; n += 1) {
      const number = await issueRepo.nextIssueNumber(org.org.id, org.project.id);
      const extra = await issueRepo.insertIssue(
        issueInput(org.org.id, org.project.id, { title: `Bulk ${n}` }),
        org.userIds.member,
        number,
      );
      await issueRepo.archiveIssue(org.org.id, extra.id);
      await backdate(org.org.id, extra.id, old);
    }

    const usageBefore = await usageRepo.getUsage(org.org.id);
    const issuesBefore = usageBefore.issuesUsed;

    await runCleanupArchivedJob(NOW);

    expect(await issueRepo.findIssueById(org.org.id, doomed.id)).toBeNull();
    expect(await issueRepo.findIssueById(org.org.id, elsewhere.id)).toBeNull();
    expect(await commentRepo.findCommentById(org.org.id, comment.id)).toBeNull();
    expect(await attachmentRepo.listAttachments(org.org.id, doomed.id)).toHaveLength(0);
    const labels = await labelRepo.listLabelsForIssues(org.org.id, [doomed.id]);
    expect(labels[doomed.id] ?? []).toHaveLength(0);

    const issueHits = await search(org.actors.member, {
      orgId: org.org.id,
      q: "PurgeMeMarker",
      kinds: ["issue"],
      limit: 10,
      cursor: null,
    });
    expect(issueHits.total).toBe(0);
    const commentHits = await search(org.actors.member, {
      orgId: org.org.id,
      q: "PurgeCommentMarker",
      kinds: ["comment"],
      limit: 10,
      cursor: null,
    });
    expect(commentHits.total).toBe(0);

    const usageAfter = await usageRepo.getUsage(org.org.id);
    expect(usageAfter.storageMbUsed).toBe(usageBefore.storageMbUsed - 3);
    expect(usageAfter.issuesUsed).toBe(issuesBefore);

    const stillThere = await issueRepo.findIssueById(org.org.id, keep.id);
    expect(stillThere?.archivedAt).not.toBeNull();

    const next = await issueRepo.nextIssueNumber(org.org.id, org.project.id);
    const created = await issueService.createIssue(
      org.actors.member,
      issueInput(org.org.id, org.project.id, { title: "After purge" }),
    );
    expect(created.number).toBe(next);
    expect(created.number).toBeGreaterThan(doomed.number);

    await expect(
      issueService.restoreIssue(org.actors.member, org.org.id, doomed.id),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("treats the cut-off instant as expired and the instant after as restorable", () => {
    const days = 30;
    const cutoff = retentionCutoff(days, NOW);
    const atCutoff = { archivedAt: cutoff };
    const justAfter = {
      archivedAt: new Date(new Date(cutoff).getTime() + 1).toISOString() as typeof cutoff,
    };
    const { isRetentionExpired } = require("@/lib/soft-delete") as typeof import("@/lib/soft-delete");
    expect(isRetentionExpired(atCutoff, days, NOW)).toBe(true);
    expect(isRetentionExpired(justAfter, days, NOW)).toBe(false);
  });
});

